#!/usr/bin/env node
/* Regenerate the shields.io endpoint badge JSONs from sources.json and
 * sources-ci.json.
 *
 * Usage (repo root):
 *   node scripts/update-benchmark-badges.js
 *
 * sources.json  — hand-recorded reference-host (Zen4) numbers.
 * sources-ci.json — CI-runner numbers, generated by the
 *                   ci-benchmark-badge workflow on master pushes.
 * The endpoint JSONs (benchmarks/badges/*.json) live on the
 * feat/ci-benchmark-badge branch; README badges on master reference them
 * via raw.githubusercontent.com. This script runs both locally and in CI.
 */
'use strict';
const fs = require('fs');
const path = require('path');

const BADGES_DIR = path.join(__dirname, '..', 'benchmarks', 'badges');

function loadSources(file) {
  const p = path.join(BADGES_DIR, file);
  if (!fs.existsSync(p)) {
    console.error('missing ' + p);
    process.exit(1);
  }
  return JSON.parse(fs.readFileSync(p, 'utf8'));
}

const src = loadSources('sources.json');
const srcCi = loadSources('sources-ci.json');
if (!Array.isArray(src.badges) || src.badges.length === 0) {
  console.error('sources.json: no badges array');
  process.exit(1);
}

let md = '';
const emit = (repo, branch, b) => {
  if (!b.id || !b.label || !b.message) {
    console.error('badge missing id/label/message: ' + JSON.stringify(b));
    process.exit(1);
  }
  const ep = {
    schemaVersion: 1,
    label: b.label,
    message: b.message,
    color: b.color || 'brightgreen',
  };
  const file = path.join(BADGES_DIR, b.id + '.json');
  fs.writeFileSync(file, JSON.stringify(ep, null, 2) + '\n');
  const url = 'https://raw.githubusercontent.com/' + repo + '/' +
              branch + '/benchmarks/badges/' + b.id + '.json';
  const shields = 'https://img.shields.io/endpoint?url=' + encodeURIComponent(url) +
                  '&style=flat-square';
  md += '[![' + b.label + '](' + shields + ')](https://github.com/' +
        repo + '#throughput)\n';
  console.log('wrote ' + file);
};

for (const b of src.badges) emit(src.repo, src.branch, b);
if (srcCi && Array.isArray(srcCi.badges)) {
  for (const b of srcCi.badges) emit(srcCi.repo, srcCi.branch, b);
}

console.log('\nREADME snippet:\n' + md);
